"""Verified English paraphrases for 32 already-rated African exclusions."""
import json
from pathlib import Path
R=Path(__file__).parent
out=[]
def q(id,topic,tags,statement,solution=None,**extra):
 item=dict(id=id,topic=topic,subtopics=tags.split('|'),statement=statement)
 if solution:item.update(solution=solution,solutionKind='original-exposition',solutionCredit='Independent mathematical exposition for Olympiad Atlas')
 item.update(extra);out.append(item)
q('mrt_7c_t3_2017_1','Geometry','Triangle centres|Trigonometry|Circles & tangency',r'Acute triangle $ABC$ has $\angle BAC=30^\circ$ and orthocentre $H$. Reflect $H$ in the midpoint of $BC$ to obtain $D$. Prove $AD=2BC$.')
q('mrt_7c_t3_2017_2','Number Theory','Divisibility & GCD|Bounds & estimation',r'Three successive discounts, at distinct positive integer percentages, reduce a garment’s price from $30000$ to $22287$ ouguiyas. Find the percentages. You may use $742900=2^2\cdot5^2\cdot17\cdot19\cdot23$.')
q('mrt_7c_t3_2017_3','Geometry','Similarity & congruence|Area & dissection|Constructions & loci',r'In right triangle $ABC$, let $\angle A=90^\circ$, $a=BC$, $b=CA$, $c=AB$. Construct two inscribed squares: one with vertex $A$, and one with a side on $BC$. Explain both constructions, express their side lengths using $b,c$, and compare their areas.')
q('mrt_7c_t3_2017_4','Number Theory','Digits & bases|Diophantine equations',r'List the positive decimal palindromes increasingly. Find the fifth and twentieth; find the ranks of the first and last three-digit palindromes. Determine the four-digit palindrome whose value divided by its rank equals $22$.')
