q('dza_2025_junior_4','Number Theory','Pigeonhole principle|Modular arithmetic|Divisibility & GCD',r'Choose nine distinct natural numbers. For each pair, list every positive divisor of their absolute difference. Prove that each integer $1,2,\ldots,8$ appears in at least one of these lists.')
q('dza_2025_benjamin_1','Number Theory','Modular arithmetic|Divisibility & GCD',r'Find all natural numbers $n$ for which $$\frac{n^6+n+61}{n^2+n+1}$$ is an integer. State separately whether $n=0$ qualifies if zero is included among the natural numbers.')
q('dza_2025_benjamin_2','Algebra','Inequalities',r'Find all positive real numbers $a_1,\ldots,a_{45}$ such that $$\sum_{k=1}^{45}\left(k^2a_k+\frac1{2025a_k}\right)=46.$$')
q('nga_senior_r2_2018_2','Number Theory','Algebraic identities|Primes|Divisibility & GCD',r'Integers $a,b,c,d$ satisfy $ab+cd=44$ and $ad-bc=9$. Find the least possible value of $a^2+b^2+c^2+d^2$.')
