q('mar_2024_december_3','Combinatorics','Pigeonhole principle|Double counting|Sets & partitions',r'A seven-member film jury reviews fifteen films, each watched by exactly four members. Find the greatest $k$ for which two films must have been watched by the same $k$ jury members.',solution=r'Each film supplies four triples of viewers, so the fifteen films supply $60$ triple occurrences among only $\binom73=35$ possible triples. Some triple therefore watched two films. To see that four common viewers cannot be guaranteed, choose fifteen distinct four-element subsets of the seven jurors as the viewing groups. Thus the maximum is $3$.')
for row in out:
 row['subtopics']=['Inequalities' if s=='Bounds & estimation' else s for s in row['subtopics']]
assert len(out)==32 and len({p['id'] for p in out})==32
(R/'restored-africa-statements.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print('Saved',len(out),'verified statements')
